const d = $input.first().json;
let prompt = 'Tu es un expert RH. Analyse le CV et la lettre ci-joints.\n\n'
  + '=== FICHE DE POSTE ===\n'
  + 'Titre: ' + d.titre_poste + '\n'
  + 'Description: ' + d.description_poste + '\n'
  + 'Competences: ' + d.competences_requises + '\n'
  + 'Experience: ' + (d.annees_experience || 'Non specifie') + '\n'
  + 'Langues: ' + (d.langues_requises || 'Non specifie') + '\n'
  + 'Contrat: ' + d.type_contrat + '\n'
  + 'Lieu: ' + d.localisation + '\n'
  + (d.exigences_ia ? '\n=== EXIGENCES PRIORITAIRES ===\n' + d.exigences_ia + '\n' : '')
  + '\nRepondre UNIQUEMENT en JSON valide:\n'
  + '{"score":7,"competences_detectees":["X"],"competences_manquantes":["Y"],"experience_annees":3,"niveau_education":"Licence","adequation_poste":"Bon profil.","points_forts":"Experience pertinente.","points_faibles":"Peu de management.","resume_analyse":"Candidat interessant.","recommandation":"QUALIFIE"}\n'
  + 'Score>=7=QUALIFIE, 4-6=A_REVOIR, <4=NON_SELECTIONNE\n'
  + 'IMPORTANT: Reponds UNIQUEMENT avec le JSON brut. Pas de bloc markdown, pas de backticks, pas de texte avant ou apres.';
const isEn = (d.company || 'solumada') === 'optimum';
if (isEn) {
  prompt += '\n\nIMPORTANT: All text fields in your JSON response MUST be in English (resume_analyse, adequation_poste, points_forts, points_faibles, competences_detectees, competences_manquantes).';
}
const content = [];
if (d.cv_base64) {
  if ((d.cv_mimetype||'').includes('pdf'))
    content.push({type:'document',source:{type:'base64',media_type:'application/pdf',data:d.cv_base64}});
  else
    content.push({type:'text',text:'=== CV ===\n'+Buffer.from(d.cv_base64,'base64').toString('utf-8')});
}
if (d.lettre_base64) {
  if ((d.lettre_mimetype||'').includes('pdf'))
    content.push({type:'document',source:{type:'base64',media_type:'application/pdf',data:d.lettre_base64}});
  else
    content.push({type:'text',text:'=== Lettre ===\n'+Buffer.from(d.lettre_base64,'base64').toString('utf-8')});
}
content.push({type:'text',text:prompt});
return [{json:{...d, requestBody:{model:'claude-sonnet-4-6',max_tokens:2048,messages:[{role:'user',content}]}}}];

const item = $input.first().json;
const raw = (item.content && item.content[0] && item.content[0].text) ? item.content[0].text : '';
// Supprimer le bloc markdown ```json ... ``` si présent
const match = raw.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
const jsonStr = match ? match[1].trim() : raw.trim();
let analyse;
try {
  analyse = JSON.parse(jsonStr);
} catch(e) {
  throw new Error('Impossible de parser la réponse Claude : ' + e.message + ' — Réponse brute : ' + raw.slice(0, 200));
}
return [{ json: { ...item, analyse } }];

const d = $('05 - Parse Claude Response').first().json;
const company = d.company || 'solumada';
const isEn = company === 'optimum';
const brand = isEn ? { name: 'Optimum Solutions', color: '#62A5D2', colorDark: '#2b6ca3', logo: 'https://optimumsolutions.eu/wp-content/uploads/2023/04/text-annotations-1.png', logoBg: '', logoHeight: 46 } : { name: 'Solumada', color: '#22c55e', colorDark: '#15803d', logo: 'https://www.solumada.mg/wp-content/uploads/2024/05/New-one.png', logoBg: '#ffffff', logoHeight: 36 };
const fromName = brand.name + ' — Recrutement';
function emailLayout({ preheader, title, subtitle, bodyHtml, ctaLabel, ctaUrl }) { subtitle = subtitle||''; ctaLabel=ctaLabel||''; ctaUrl=ctaUrl||''; const year=new Date().getFullYear(); const logoBlock=brand.logoBg?`<table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="background:${brand.logoBg};border-radius:14px;padding:13px 20px;box-shadow:0 6px 18px rgba(0,0,0,.12)"><img src="${brand.logo}" alt="${brand.name}" height="${brand.logoHeight}" style="display:block;height:${brand.logoHeight}px;max-height:${brand.logoHeight}px;max-width:180px;border:0;outline:none"></td></tr></table>`:`<img src="${brand.logo}" alt="${brand.name}" height="${brand.logoHeight}" style="display:block;height:${brand.logoHeight}px;max-height:${brand.logoHeight}px;max-width:210px;border:0;outline:none">`; const cta=(ctaLabel&&ctaUrl)?`<tr><td align="center" style="padding:6px 32px 4px"><a href="${ctaUrl}" style="display:inline-block;background:${brand.color};color:#ffffff;text-decoration:none;font-weight:700;font-size:15px;padding:15px 38px;border-radius:10px">${ctaLabel}</a></td></tr>`:''; const footerNote=isEn?'Recruitment · Please do not reply directly to this email.':'Service Recrutement · Merci de ne pas répondre directement à cet email.'; const copyright=isEn?'All rights reserved':'Tous droits réservés'; return `<!DOCTYPE html><html lang="${isEn?'en':'fr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body style="margin:0;padding:0;background:#eef2f6;-webkit-font-smoothing:antialiased"><span style="display:none!important;font-size:0;line-height:0;max-height:0;opacity:0;overflow:hidden;mso-hide:all">${preheader}</span><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef2f6;padding:30px 12px"><tr><td align="center"><table role="presentation" width="600" cellpadding="0" cellspacing="0" style="max-width:600px;width:100%;background:#ffffff;border-radius:18px;overflow:hidden;box-shadow:0 12px 44px rgba(15,23,42,.12);font-family:'Segoe UI',Roboto,Helvetica,Arial,sans-serif"><tr><td style="background:linear-gradient(135deg,${brand.colorDark} 0%,${brand.color} 100%);padding:34px 24px 30px" align="center">${logoBlock}<h1 style="margin:20px 0 0;color:#ffffff;font-size:23px;font-weight:800;letter-spacing:-.02em">${title}</h1>${subtitle?`<p style="margin:9px 0 0;color:rgba(255,255,255,.88);font-size:14px;font-weight:500">${subtitle}</p>`:''}</td></tr><tr><td style="padding:34px 32px 10px;color:#334155;font-size:15px;line-height:1.65">${bodyHtml}</td></tr>${cta}<tr><td style="padding:30px 32px 32px"><table role="presentation" width="100%"><tr><td style="border-top:1px solid #eef2f6;padding-top:20px"><p style="margin:0;color:#64748b;font-size:13px;font-weight:700">${brand.name}</p><p style="margin:4px 0 0;color:#94a3b8;font-size:12px;line-height:1.6">${footerNote}</p></td></tr></table></td></tr></table><p style="margin:18px 0 0;color:#cbd5e1;font-size:11px">© ${year} ${brand.name} — ${copyright}</p></td></tr></table></body></html>`; }
function detailTable(rows) { const trs=rows.filter(Boolean).map(([label,value])=>`<tr><td style="padding:12px 16px;background:#f8fafc;border-bottom:1px solid #eef2f6;font-weight:600;color:#475569;font-size:13px;width:38%">${label}</td><td style="padding:12px 16px;border-bottom:1px solid #eef2f6;color:#0f172a;font-size:14px;font-weight:500">${value}</td></tr>`).join(''); return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border-spacing:0;border:1px solid #eef2f6;border-radius:12px;overflow:hidden;margin:20px 0">${trs}</table>`; }
const table = detailTable([[isEn?'Position':'Poste',d.titre_poste],[isEn?'Contract':'Contrat',d.type_contrat],[isEn?'Location':'Localisation',d.localisation]]);
const bodyHtml = isEn
  ? `<p style="margin:0 0 14px">Hello <strong>${d.candidat_nom}</strong>,</p><p style="margin:0 0 14px">Thank you for your interest in our company.</p><p style="margin:0 0 6px">We have received your application for the position of <strong>${d.titre_poste}</strong>.</p>${table}<p style="margin:6px 0 0;color:#64748b;font-size:13px">Our team will review your file as soon as possible. You will be contacted if your profile matches our needs.</p>`
  : `<p style="margin:0 0 14px">Bonjour <strong>${d.candidat_nom}</strong>,</p><p style="margin:0 0 14px">Nous vous remercions de l'intérêt que vous portez à notre entreprise.</p><p style="margin:0 0 6px">Nous avons bien reçu votre candidature pour le poste de <strong>${d.titre_poste}</strong>.</p>${table}<p style="margin:6px 0 0;color:#64748b;font-size:13px">Notre équipe examinera votre dossier dans les meilleurs délais. Vous serez recontacté(e) si votre profil correspond à nos besoins.</p>`;
return [{ json: { fromName, to: d.candidat_email, subject: isEn?`📩 Application received — ${d.titre_poste}`:`📩 Candidature reçue — ${d.titre_poste}`, html: emailLayout({ preheader: isEn?`Your application for ${d.titre_poste} has been received`:`Votre candidature pour ${d.titre_poste} a bien été reçue`, title: isEn?'Application Received ✅':'Candidature bien reçue ✅', subtitle: d.titre_poste, bodyHtml }), replyTo: d.email_recruteur || '' }}];
